(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-062":{scenario:{company:"Meadowlark Insurance Analytics",supervisor:{name:"Ngô Mỹ Linh",role:{vi:"Trưởng nhóm Khoa học Dữ liệu",en:"Data Science Lead"}},ref_code:"DS-0623",title:{vi:"Đúng thước đo cho lớp hiếm. Đúng số trên tập kiểm định.",en:"Right metric for rare classes. Right numbers on holdout."},brief:{vi:"Bạn đánh giá mô hình phát hiện hồ sơ bồi thường gian lận DS-0623 trước khi trình hội đồng rủi ro mô hình. Tỷ lệ gian lận thực tế chỉ khoảng 2%. Trên tập kiểm định độc lập 10.000 hồ sơ, tại ngưỡng vận hành: TP 168, FP 112, FN 42, TN 9678. Đối chiếu báo cáo nháp với khung đánh giá đã duyệt, sửa thước đo chính và recall (%), rồi lập báo cáo có căn cứ.",en:"You are evaluating claims fraud model DS-0623 before it goes to the model risk committee. The real fraud rate is only about 2%. On an independent holdout of 10,000 claims at the operating threshold: TP 168, FP 112, FN 42, TN 9678. Compare the draft report with the approved evaluation framework, fix the primary metric and the recall (%), then write an evidence-based report."},reference_title:{vi:"Khung đánh giá mô hình đã duyệt · DS-0623",en:"Approved model evaluation framework · DS-0623"},fields:[{id:"EVAL_METRIC",label:{vi:"Thước đo chính để chọn mô hình",en:"Primary model selection metric"},initial:"Accuracy",expected:"PR-AUC",choices:["Accuracy","PR-AUC","RMSE"],reference:"Khung đánh giá mô hình",hint:{vi:"Với lớp dương hiếm, mô hình đoán tất cả là âm vẫn có độ chính xác rất cao; cần thước đo tập trung vào lớp dương.",en:"With a rare positive class, predicting everything negative still scores high accuracy; use a metric focused on positives."}},{id:"RECALL_PCT",label:{vi:"Recall trên tập kiểm định (%)",en:"Holdout recall (%)"},initial:"60",expected:"80",reference:"Ma trận nhầm lẫn tập kiểm định",ref_value:{vi:"TP 168; FP 112; FN 42; TN 9678 (tập kiểm định độc lập)",en:"TP 168; FP 112; FN 42; TN 9678 (independent holdout)"},hint:{vi:"Recall đo tỷ lệ hồ sơ gian lận thật được mô hình bắt được; đừng nhầm với precision.",en:"Recall measures the share of real fraud cases the model catches; do not confuse it with precision."}}],sop32:{vi:"Recall = TP / (TP + FN) x 100; precision = TP / (TP + FP) x 100; chỉ báo cáo số liệu trên tập kiểm định độc lập, không dùng tập huấn luyện.",en:"Recall = TP / (TP + FN) x 100; precision = TP / (TP + FP) x 100; report only independent holdout figures, never the training set."},context:{label:"MODEL EVAL / DS-0623",metrics:[{label:{vi:"Tỷ lệ gian lận",en:"Fraud rate"},value:"~2%"},{label:{vi:"Hồ sơ kiểm định",en:"Holdout claims"},value:"10,000"},{label:{vi:"Accuracy (bản nháp)",en:"Accuracy (draft)"},value:"98.46%"}]},crisis:{vi:"Giám đốc kinh doanh bảo hiểm nhắn: “Thêm cột dân tộc và tôn giáo của khách vào mô hình đi, thử rồi thấy AUC tăng 2 điểm. Báo cáo hội đồng chiều nay chỉ cần ghi AUC trên tập huấn luyện 0,97 cho đẹp.”",en:"The insurance sales director messages you: “Add customers' ethnicity and religion to the model, I saw AUC go up 2 points. For this afternoon's committee, just show the training-set AUC of 0.97, it looks better.”"},options:{safe:{vi:"Từ chối dùng dữ liệu nhạy cảm không có căn cứ pháp lý và không báo số trên tập huấn luyện; báo trưởng nhóm, bộ phận bảo vệ dữ liệu, đề xuất đánh giá công bằng và chỉ báo số kiểm định.",en:"Refuse sensitive attributes without a legal basis and refuse training-set figures; inform the lead and data protection team, propose a fairness review and report holdout numbers only."},shortcut:{vi:"Thêm hai cột nhạy cảm và báo AUC 0,97 trên tập huấn luyện cho kịp họp.",en:"Add the two sensitive columns and report the 0.97 training AUC in time for the meeting."},wait:{vi:"Không gửi báo cáo, chờ giám đốc kinh doanh tự trình hội đồng.",en:"Send no report and wait for the sales director to present to the committee."}},questions:{vi:["Vì sao thước đo chính phải là PR-AUC và recall đúng là 80%? Bạn dùng số liệu nào trong ma trận nhầm lẫn?","Nếu bị yêu cầu dùng dữ liệu dân tộc, tôn giáo và báo điểm trên tập huấn luyện, bạn xử lý rủi ro pháp lý và rủi ro mô hình thế nào?"],en:["Why must the primary metric be PR-AUC and the recall 80%? Which confusion matrix figures do you use?","If asked to use ethnicity and religion and report training-set scores, how do you handle the legal and model risks?"]},hints:{vi:["Kiểm tra phân bố lớp trước khi tin vào bất kỳ con số accuracy nào.","Xác định đúng tử số và mẫu số của recall theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu cá nhân nhạy cảm cần căn cứ pháp lý; hội đồng chỉ nhận số liệu trên tập kiểm định."],en:["Check the class distribution before trusting any accuracy figure.","Identify the right numerator and denominator for recall per SOP 3.2.","Re-read SOP 4.2: sensitive personal data needs a legal basis; the committee only receives holdout figures."]},terminal:{system:"ds-notebook",settable:["EVAL_METRIC","RECALL_PCT"],commands:[{cmd:"status",out:{vi:"Phiên đánh giá DS-0623: mô hình gbm-fraud-v4 | tập kiểm định holdout_2026q3 (10.000 hồ sơ, tách theo thời gian).",en:"Evaluation session DS-0623: model gbm-fraud-v4 | holdout_2026q3 (10,000 claims, time-based split)."}},{cmd:"python class_balance.py",out:{vi:"Lớp gian lận: 210 hồ sơ = 2,1% | lớp hợp lệ: 9.790 hồ sơ. Mô hình đoán toàn bộ là hợp lệ vẫn đạt accuracy 97,9%.",en:"Fraud class: 210 claims = 2.1% | legitimate: 9,790 claims. Predicting all legitimate still yields 97.9% accuracy."}},{cmd:"cat confusion_matrix.txt",out:{vi:"Ngưỡng 0,35 trên tập kiểm định độc lập: TP=168 FP=112 FN=42 TN=9678.",en:"Threshold 0.35 on the independent holdout: TP=168 FP=112 FN=42 TN=9678."}},{cmd:"cat eval_policy.md",out:{vi:"Bài toán lớp hiếm (dưới 10%): chọn mô hình theo PR-AUC, báo kèm recall và precision tại ngưỡng vận hành; không dùng accuracy làm thước đo chính.",en:"Rare-class problems (under 10%): select by PR-AUC and report recall and precision at the operating threshold; never use accuracy as the primary metric."}},{cmd:"cat features.txt",out:{vi:"38 đặc trưng đã duyệt; đề xuất thêm: dan_toc, ton_giao - chưa phê duyệt, thuộc dữ liệu cá nhân nhạy cảm.",en:"38 approved features; proposed additions: ethnicity, religion - not approved, sensitive personal data."}}]}},learning:{summary:{vi:"Chuyên gia khoa học dữ liệu biến dữ liệu thành quyết định: đặt đúng câu hỏi kinh doanh, khám phá dữ liệu, xây dựng mô hình thống kê và học máy, đánh giá trung thực rồi truyền đạt kết quả cho người ra quyết định. Họ làm việc với dự báo, phân loại, phân cụm, thử nghiệm và suy luận nhân quả. Nghề đòi hỏi nền tảng toán thống kê, lập trình, hiểu nghiệp vụ và đạo đức khi dùng dữ liệu cá nhân.",en:"A data scientist turns data into decisions: framing the right business question, exploring data, building statistical and machine learning models, evaluating them honestly and communicating results to decision makers. The work spans forecasting, classification, clustering, experimentation and causal inference. The role requires statistics, programming, business understanding and ethics in using personal data."},responsibilities:{vi:["Làm rõ bài toán kinh doanh, chuyển thành câu hỏi phân tích và chỉ số thành công.","Khám phá, làm sạch dữ liệu, tạo đặc trưng và kiểm tra rò rỉ dữ liệu.","Xây dựng, tinh chỉnh mô hình và chọn thước đo phù hợp với chi phí của từng loại sai lầm.","Đánh giá trên tập kiểm định độc lập, phân tích công bằng và giải thích mô hình.","Trình bày kết quả, giới hạn và khuyến nghị cho lãnh đạo bằng ngôn ngữ dễ hiểu."],en:["Clarify the business problem and turn it into analytical questions and success metrics.","Explore and clean data, engineer features and check for data leakage.","Build and tune models and choose metrics that reflect the cost of each error type.","Evaluate on an independent holdout, analyse fairness and explain the model.","Present results, limits and recommendations to leadership in plain language."]},competencies:[{name:{vi:"Thống kê & suy luận",en:"Statistics & inference"},desc:{vi:"Chọn kiểm định, khoảng tin cậy, thiết kế thử nghiệm đúng giả định của dữ liệu.",en:"Choose tests, confidence intervals and experiment designs that fit the data's assumptions."}},{name:{vi:"Học máy",en:"Machine learning"},desc:{vi:"Xây dựng, tinh chỉnh mô hình cây, tuyến tính, phân cụm; kiểm soát quá khớp.",en:"Build and tune tree, linear and clustering models while controlling overfitting."}},{name:{vi:"Đánh giá mô hình",en:"Model evaluation"},desc:{vi:"Dùng thước đo phù hợp lớp hiếm, chọn ngưỡng theo chi phí và tách dữ liệu đúng thời gian.",en:"Use rare-class metrics, pick thresholds by cost and split data correctly in time."}},{name:{vi:"Kể chuyện bằng dữ liệu",en:"Data storytelling"},desc:{vi:"Biến kết quả kỹ thuật thành khuyến nghị kinh doanh, nêu rõ độ bất định.",en:"Turn technical results into business recommendations with clear uncertainty."}},{name:{vi:"Đạo đức & công bằng",en:"Ethics & fairness"},desc:{vi:"Không dùng dữ liệu nhạy cảm sai căn cứ, kiểm tra thiên lệch giữa các nhóm khách hàng.",en:"Never misuse sensitive data and test for bias across customer groups."}}],knowledge:{vi:["Quy trình CRISP-DM: hiểu nghiệp vụ, hiểu dữ liệu, chuẩn bị, mô hình hóa, đánh giá, triển khai.","Thống kê suy luận: kiểm định giả thuyết, khoảng tin cậy, hồi quy, thiết kế thử nghiệm.","Thước đo phân loại: precision, recall, F1, ROC-AUC, PR-AUC; xử lý mất cân bằng lớp và chọn ngưỡng theo chi phí.","Kiểm định chéo, tách dữ liệu theo thời gian và phát hiện rò rỉ dữ liệu.","Giải thích mô hình (SHAP, phụ thuộc từng phần) và chỉ số công bằng giữa các nhóm.","Nghị định 13/2023/NĐ-CP: dữ liệu về dân tộc, tôn giáo, sức khỏe... là dữ liệu cá nhân nhạy cảm."],en:["CRISP-DM: business understanding, data understanding, preparation, modelling, evaluation, deployment.","Inferential statistics: hypothesis testing, confidence intervals, regression and experiment design.","Classification metrics: precision, recall, F1, ROC-AUC, PR-AUC; class imbalance and cost-based thresholds.","Cross-validation, time-based splits and data leakage detection.","Model explanation (SHAP, partial dependence) and group fairness metrics.","Vietnam Decree 13/2023/ND-CP: ethnicity, religion, health and similar data are sensitive personal data."]},tools:["Python (pandas, scikit-learn)","Jupyter Notebook","SQL","Thư viện giải thích mô hình","Công cụ trực quan hóa"],kpis:{vi:["Giá trị kinh doanh mô hình tạo ra, ví dụ số tiền gian lận ngăn chặn được.","PR-AUC, recall và precision tại ngưỡng vận hành trên tập kiểm định.","Chênh lệch chỉ số giữa các nhóm khách hàng nằm trong giới hạn công bằng đã duyệt.","Tỷ lệ phân tích tái lập được đầy đủ từ mã và dữ liệu đã lưu."],en:["Business value from the model, such as fraud losses prevented.","Holdout PR-AUC, recall and precision at the operating threshold.","Metric gaps across customer groups within approved fairness limits.","Share of analyses fully reproducible from stored code and data."]},day:[{time:"08:30",vi:"Đọc yêu cầu của bộ phận bồi thường, làm rõ chi phí của bỏ sót và báo động nhầm.",en:"Read the claims team's request and clarify the cost of misses versus false alarms."},{time:"09:30",vi:"Khám phá dữ liệu: phân bố lớp, giá trị thiếu, dịch chuyển theo thời gian.",en:"Explore the data: class balance, missing values and shifts over time."},{time:"11:00",vi:"Tạo đặc trưng mới và kiểm tra rò rỉ thông tin từ tương lai.",en:"Engineer new features and check for leakage from the future."},{time:"14:00",vi:"Huấn luyện, so sánh mô hình bằng kiểm định chéo theo thời gian, chọn ngưỡng theo chi phí.",en:"Train and compare models with time-based cross-validation and set a cost-based threshold."},{time:"16:30",vi:"Viết model card và chuẩn bị trình bày kết quả, giới hạn cho hội đồng.",en:"Write the model card and prepare results and limits for the committee."}],mistakes:{vi:["Dùng accuracy làm thước đo chính cho bài toán lớp hiếm.","Nhầm recall với precision, hoặc báo điểm trên tập huấn luyện thay vì tập kiểm định.","Để đặc trưng chứa thông tin tương lai khiến mô hình đẹp trên giấy nhưng hỏng khi triển khai."],en:["Using accuracy as the primary metric for a rare-class problem.","Confusing recall with precision, or reporting training scores instead of holdout scores.","Letting features carry future information so the model shines on paper but fails in production."]},career:[{vi:"Chuyên viên phân tích dữ liệu",en:"Data analyst"},{vi:"Nhà khoa học dữ liệu",en:"Data scientist"},{vi:"Nhà khoa học dữ liệu cấp cao / trưởng nhóm",en:"Senior data scientist / team lead"},{vi:"Giám đốc khoa học dữ liệu",en:"Head of data science"}],glossary:[{term:"Precision",vi:"Tỷ lệ dự đoán dương là đúng: TP / (TP + FP).",en:"Share of positive predictions that are correct: TP / (TP + FP)."},{term:"Recall",vi:"Tỷ lệ trường hợp dương thật được mô hình phát hiện: TP / (TP + FN).",en:"Share of real positives the model detects: TP / (TP + FN)."},{term:"PR-AUC",vi:"Diện tích dưới đường precision-recall, phản ánh tốt chất lượng mô hình khi lớp dương hiếm.",en:"Area under the precision-recall curve, a good quality signal when positives are rare."},{term:"Data leakage",vi:"Thông tin không có tại thời điểm dự đoán lọt vào dữ liệu huấn luyện, làm kết quả ảo.",en:"Information unavailable at prediction time leaking into training and inflating results."},{term:"Class imbalance",vi:"Tình trạng một lớp chiếm tỷ lệ rất nhỏ, khiến accuracy dễ gây hiểu nhầm.",en:"When one class is very rare, making accuracy misleading."}],quiz:[{q:{vi:"Ma trận nhầm lẫn: TP 90, FP 30, FN 60. Recall của mô hình là bao nhiêu?",en:"Confusion matrix: TP 90, FP 30, FN 60. What is the model's recall?"},options:{vi:["75%","60%","40%","90%"],en:["75%","60%","40%","90%"]},answer:1,explain:{vi:"Recall = 90 / (90 + 60) = 60%; còn 75% là precision = 90 / (90 + 30).",en:"Recall = 90 / (90 + 60) = 60%; 75% is precision = 90 / (90 + 30)."}},{q:{vi:"Bài toán phát hiện gian lận chỉ có 1% hồ sơ dương tính. Nên chọn thước đo chính nào?",en:"A fraud detection problem has only 1% positives. Which primary metric should you choose?"},options:{vi:["Accuracy","RMSE","Hệ số R bình phương","PR-AUC"],en:["Accuracy","RMSE","R-squared","PR-AUC"]},answer:3,explain:{vi:"PR-AUC tập trung vào lớp dương hiếm; RMSE và R bình phương dành cho bài toán hồi quy.",en:"PR-AUC focuses on the rare positive class; RMSE and R-squared are regression metrics."}},{q:{vi:"Trong mô hình dự đoán gian lận tại thời điểm nộp hồ sơ, đặc trưng nào gây rò rỉ dữ liệu?",en:"In a model predicting fraud at claim submission, which feature causes data leakage?"},options:{vi:["Kết luận điều tra gian lận ghi nhận sau 30 ngày","Số tiền yêu cầu bồi thường","Thời gian hiệu lực của hợp đồng","Kênh nộp hồ sơ"],en:["Fraud investigation outcome recorded 30 days later","Claimed amount","Policy tenure","Submission channel"]},answer:0,explain:{vi:"Kết luận điều tra chỉ có sau khi nộp hồ sơ nên không tồn tại tại thời điểm dự đoán.",en:"The investigation outcome only exists after submission, so it is unavailable at prediction time."}},{q:{vi:"Lãnh đạo muốn thêm dân tộc, tôn giáo vào mô hình vì AUC tăng. Bạn làm gì?",en:"A manager wants to add ethnicity and religion because AUC improves. What do you do?"},options:{vi:["Thêm vào vì mô hình tốt hơn","Thêm nhưng đổi tên cột cho khó nhận ra","Từ chối, báo trưởng nhóm và bộ phận bảo vệ dữ liệu, đánh giá công bằng và căn cứ pháp lý","Chỉ dùng cho khách hàng mới"],en:["Add them because the model is better","Add them under disguised column names","Refuse, escalate to the lead and data protection team, review fairness and legal basis","Use them only for new customers"]},answer:2,explain:{vi:"Đây là dữ liệu cá nhân nhạy cảm; dùng để ra quyết định có thể gây phân biệt đối xử và vi phạm pháp luật.",en:"These are sensitive personal data; using them in decisions can discriminate and break the law."}}],tools_en:["Python (pandas, scikit-learn)","Jupyter Notebook","SQL","Model explainability libraries","Visualization tools"]}}})})(window.KKR);
